function staffForm(editIndex=null){const x=editIndex===null?null:staffUsers[editIndex];openModal(`<h2>${x?'Edit pengguna':'Tambah pengguna'}</h2><p>Profil karyawan dan penempatan operasional. Akun masuk dibuat terpisah melalui Master login.</p><div class="form-grid"><label>Nama lengkap<input id="staffName" value="${x?.name||''}" placeholder="Nama karyawan"></label><label>Jabatan<select id="staffRole"><option ${x?.role==='Kasir'?'selected':''}>Kasir</option><option ${x?.role==='Kepala Toko'?'selected':''}>Kepala Toko</option><option ${x?.role==='Administrator'?'selected':''}>Administrator</option><option ${x?.role==='Owner'?'selected':''}>Owner</option></select></label><label>Outlet penempatan<select id="staffOutlet"><option>Sekulan RBT 519A</option><option>Semua outlet</option></select></label><label>Shift kerja<select id="staffShift"><option>-</option><option ${x?.shift==='Shift 1'?'selected':''}>Shift 1</option><option ${x?.shift==='Shift 2'?'selected':''}>Shift 2</option><option ${x?.shift==='Shift 3'?'selected':''}>Shift 3</option></select></label><label>Nomor telepon<input id="staffPhone" value="${x?.phone||''}" placeholder="08xxxxxxxxxx"></label><label>Status<select id="staffStatus"><option ${x?.status==='Aktif'?'selected':''}>Aktif</option><option ${x?.status==='Nonaktif'?'selected':''}>Nonaktif</option></select></label></div><div class="modal-actions"><button class="btn ghost" data-close>Batal</button><button class="btn primary" id="saveStaff">Simpan pengguna</button></div>`);$('#saveStaff').onclick=()=>{const name=$('#staffName').value.trim();if(!name)return showToast('Nama pengguna wajib diisi');const value={initial:name.split(' ').map(v=>v[0]).join('').slice(0,2).toUpperCase(),name,role:$('#staffRole').value,outlet:$('#staffOutlet').value,shift:$('#staffShift').value,phone:$('#staffPhone').value,status:$('#staffStatus').value};if(x)staffUsers[editIndex]=value;else staffUsers.push(value);renderStaffUsers();closeModal();showToast('Profil pengguna berhasil disimpan')}}
function openCancel(i){if(!cart[i])return;const item=cart[i],saved=!!item.saved,n=closingShift(),leader=shiftLeader(n);openModal(`<h2>Batalkan item?</h2><div class="warning-box"><strong>Owner akan menerima peringatan</strong><span>${saved?`Item ini sudah tersimpan di order ${activeOrder.id}. Pembatalan memerlukan otorisasi Kepala Toko Shift ${n} dan otomatis masuk histori serta BA tutup shift.`:'Cancel tidak memerlukan kata sandi dan otomatis masuk histori serta BA tutup shift.'}</span></div>${saved?`<label>Jumlah dibatalkan (maks. ${item.qty})</label><input id="cancelQty" type="number" min="1" max="${item.qty}" value="${item.qty}">`:''}<label>Alasan pembatalan</label><select id="cancelReason"><option>Salah pilih menu</option><option>Perubahan pesanan pelanggan</option><option>Stok tidak tersedia</option><option>Lainnya</option></select><label>Catatan kasir</label><input id="cancelNote" placeholder="Tambahkan penjelasan singkat">${saved?`<div class="approver-row">Shift ${n} · Kepala Toko: <strong>${leader?.name||'-'}</strong></div><label>Username Kepala Toko</label><input id="cancelAuthUser" autocomplete="off" placeholder="nama.login" value="${leader?.username||''}"><label>Kata sandi</label><input id="cancelAuthPass" type="password" autocomplete="off" value="demo123">`:''}<div class="modal-actions"><button class="btn ghost" data-close>Kembali</button><button class="btn danger" id="confirmCancel">Batalkan & beri tahu owner</button></div>`);$('#confirmCancel').onclick=()=>{const reason=$('#cancelReason').value,note=$('#cancelNote').value.trim();if(reason==='Lainnya'&&!note)return showToast('Catatan kasir wajib diisi untuk alasan Lainnya');let qty=item.qty,label=item.name;if(saved){qty=Math.floor(+$('#cancelQty').value||0);if(qty<1||qty>item.qty)return showToast(`Jumlah dibatalkan harus 1–${item.qty}`);const u=$('#cancelAuthUser').value,pw=$('#cancelAuthPass').value;if(!u.trim()||!pw)return showToast('Username dan kata sandi Kepala Toko wajib diisi');const r=findAccount(u,pw);if(r.error==='invalid')return showToast('Kredensial Kepala Toko tidak valid');if(r.account.role!=='Kepala Toko')return showToast('Akun ini bukan Kepala Toko');if(r.error==='inactive')return showToast('Akun Kepala Toko tidak aktif');if(r.account.outlet!=='Sekulan RBT 519A'||r.account.shift!==`Shift ${n}`)return showToast(`Hanya Kepala Toko Shift ${n} (${leader?.name||'-'}) yang dapat menyetujui pembatalan ini`);label=`${item.name}${qty<item.qty?` ×${qty}`:''} (${activeOrder.id})`;const oi=activeOrder.items.find(x=>x.name===item.name);if(oi){oi.qty-=qty;if(oi.qty<=0)activeOrder.items.splice(activeOrder.items.indexOf(oi),1)}item.qty-=qty}cancelLog.unshift([`CNL-0920-00${cancelLog.length+1}`,'20 Sep 2026 13.02','Shift 1',label,note?`${reason} — ${note}`:reason,'Ayu Setiani','Menunggu BA']);if(!saved||item.qty<=0)cart.splice(i,1);renderCart();renderCancelHistory();renderOrders();closeModal();showToast('Cancel tercatat. Peringatan dikirim ke owner.')}}
function productionModal(){
  let lines=[{i:0,qty:8}];
  openModal(`<div class="req-modal prod-modal"><h2>Catat hasil produksi</h2><p>Bahan baku berkurang dan nilainya dibukukan sebagai biaya bahan baku. Hasil produksi masuk ke LPP barang dagangan.</p><div class="form-grid"><label>Hasil barang dagangan<select id="finishedItem">${finishedStock.map((x,i)=>x.shared?'':`<option value="${i}">${x.name}</option>`).join('')}</select></label><label>Jumlah hasil<input id="finishedQty" type="number" value="40" min="1"></label></div><table class="stock-table"><thead><tr><th>BAHAN BAKU</th><th>STOK</th><th>QTY DIPAKAI</th><th>BIAYA</th><th></th></tr></thead><tbody id="prodLines"></tbody></table><button class="btn ghost" id="addProdLine">+ Tambah bahan</button><div class="cost-preview" id="costPreview"></div><div class="modal-actions"><button class="btn ghost" data-close>Batal</button><button class="btn primary" id="confirmProduction">Catat produksi</button></div></div>`);
  const total=()=>lines.reduce((s,l)=>s+rawStock[l.i].cost*(l.qty||0),0),sum=()=>{const t=total(),fq=+$('#finishedQty').value||0;$('#costPreview').textContent=`Total biaya bahan ${rupiah(t)} · HPP/unit ${rupiah(fq>0?Math.round(t/fq):0)}`};
  const draw=()=>{$('#prodLines').innerHTML=lines.map((l,n)=>{const x=rawStock[l.i];return `<tr><td><select class="prod-raw" data-line="${n}">${rawStock.map((r,i)=>r.shared?'':`<option value="${i}" ${i===l.i?'selected':''}>${r.name}</option>`).join('')}</select></td><td class="muted">${x.qty} ${x.unit}</td><td><input class="prod-qty" data-line="${n}" type="number" min="0" value="${l.qty}"></td><td class="prod-cost">${rupiah(x.cost*l.qty)}</td><td><button class="prod-del" data-line="${n}" title="Hapus baris">×</button></td></tr>`}).join('');
    $$('.prod-raw').forEach(s=>s.onchange=()=>{lines[+s.dataset.line].i=+s.value;draw()});$$('.prod-qty').forEach(e=>e.oninput=()=>{const l=lines[+e.dataset.line];l.qty=+e.value||0;e.closest('tr').querySelector('.prod-cost').textContent=rupiah(rawStock[l.i].cost*l.qty);sum()});$$('.prod-del').forEach(b=>b.onclick=()=>{lines.splice(+b.dataset.line,1);draw()});sum()};
  draw();$('#finishedQty').oninput=sum;
  $('#addProdLine').onclick=()=>{const i=rawStock.findIndex((r,k)=>!r.shared&&!lines.some(l=>l.i===k));if(i<0)return showToast('Semua bahan baku sudah dipilih');lines.push({i,qty:1});draw()};
  $('#confirmProduction').onclick=()=>{const use=lines.filter(l=>l.qty>0),fq=+$('#finishedQty').value||0,fin=finishedStock[+$('#finishedItem').value];if(!use.length)return showToast('Tambahkan minimal satu bahan baku');if(fq<=0)return showToast('Jumlah hasil produksi harus diisi');const bad=use.find(l=>l.qty>rawStock[l.i].qty);if(bad){const r=rawStock[bad.i];return showToast(`Stok ${r.name} tidak mencukupi (tersedia ${r.qty} ${r.unit})`)}const t=total(),hpp=Math.round(t/fq);use.forEach(l=>rawStock[l.i].qty-=l.qty);fin.qty+=fq;fin.cost=hpp;const kode=`PRD-0920-${String(prdSeq++).padStart(3,'0')}`;stockMoves.unshift([kode,use.map(l=>`${rawStock[l.i].name} ${l.qty} ${rawStock[l.i].unit}`).join(' + '),`Menjadi ${fq} ${fin.name}`,reqNow().slice(-5)]);productionLog.unshift({id:kode,at:reqNow(),product:fin.name,qty:fq,unit:fin.unit,lines:use.map(l=>({name:rawStock[l.i].name,qty:l.qty,unit:rawStock[l.i].unit})),total:t,hpp,by:session.name});renderInventory();closeModal();showToast(`Produksi ${kode} tercatat. ${fq} ${fin.unit} ${fin.name} masuk, biaya ${rupiah(t)} dibukukan.`)};
}
