let orderFilter='Semua',orderOutlet='Semua outlet',orderQuery='',orderDraft={category:'Paket',items:[],query:''};
function moneyState(total,paid){return paid>total?'Lebih bayar':total-paid===0?'Lunas':paid>0?'Sebagian':'Belum bayar'}
function orderMoney(o){const total=o.items.reduce((s,x)=>s+x.price*x.qty,0),paid=o.payments.reduce((s,p)=>s+p.amount,0);return {total,paid,rest:total-paid,state:moneyState(total,paid)}}
function stateCls(s){return s==='Lunas'?'live':s==='Lebih bayar'?'over':'alert'}
function payPill(o){const s=orderMoney(o).state;return `<span class="status ${stateCls(s)}">${s}</span>`}
function orderPill(o){return `<span class="status ${o.status==='Open'?'live':''}">${o.status}</span>`}
function fmtEta(o){const [y,m,d]=o.date.split('-');return `${+d} ${MONTHS[m-1]} ${y} ${o.time.replace(':','.')}`}
function nextOrderId(){return `ORD-0920-${String(scheduledOrders.length+1).padStart(3,'0')}`}
