function rokokPickerHtml(items){return `<div class="rokok-picker-list">${menuData.Rokok.map(([name])=>{const q=items.find(x=>x.name===name)?.qty,s=finishedStock.find(x=>x.name===name);return `<div class="rokok-row"><strong>${name}</strong><small>Stok ${s?s.qty:0} bungkus</small><input type="number" min="0" class="rokok-qty" data-name="${name}" value="${q||''}" placeholder="0"></div>`}).join('')}</div>`}
function readRokokPicker(root){return [...root.querySelectorAll('.rokok-qty')].map(i=>({name:i.dataset.name,qty:+i.value||0})).filter(x=>x.qty>0)}
function cutFinished(lines){lines.forEach(c=>{const s=finishedStock.find(x=>x.name===c.name);if(s)s.qty=Math.max(0,s.qty-c.qty)})}
function byEta(a,b){return (a.date+a.time).localeCompare(b.date+b.time)}
function deductOrderStock(o){cutFinished(o.items.concat(o.fee?.type==='stock'?o.fee.items:[]));renderInventory()}
function completeOrder(o){o.status='Selesai';deductOrderStock(o)}
function visibleOrders(){const kt=session?.role==='Kepala Toko',q=orderQuery.trim().toLowerCase();return scheduledOrders.filter(o=>(kt?o.outlet===session.outlet:orderOutlet==='Semua outlet'||o.outlet===orderOutlet)&&(orderFilter==='Semua'||o.status===orderFilter)&&(!q||`${o.id} ${o.customer}`.toLowerCase().includes(q))).sort(byEta)}
function renderOrders(){const kt=session?.role==='Kepala Toko',sel=$('#orderOutletFilter');sel.classList.toggle('hidden',kt);sel.innerHTML=['Semua outlet',...outlets.map(x=>x.name)].map(x=>`<option ${x===orderOutlet?'selected':''}>${x}</option>`).join('');$('#orderStatusFilter').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.status===orderFilter));const list=visibleOrders();$('#orderCount').textContent=`${list.length} order${kt?` • ${session.outlet}`:''} • klik baris untuk detail`;$('#orderTable').innerHTML=list.length?tableHtml(['ESTIMASI','NO','PELANGGAN','OUTLET','TOTAL','BAYAR','STATUS'],list.map(o=>{const m=orderMoney(o);return [fmtEta(o),o.id,o.customer,o.outlet,rupiah(m.total),`${payPill(o)}${m.rest>0?`<small class="order-rest">sisa ${rupiah(m.rest)}</small>`:m.rest<0?`<small class="order-rest over-text">lebih ${rupiah(-m.rest)}</small>`:''}`,orderPill(o)]})):`<div class="empty-cart">Tidak ada order yang cocok.</div>`;$('#orderTable').querySelectorAll('tbody tr').forEach((tr,i)=>tr.onclick=()=>openOrderDetail(list[i].id))}
function openOrderDetail(id){const o=scheduledOrders.find(x=>x.id===id),m=orderMoney(o);openModal(`<h2>${o.id}</h2><p>${o.customer}${o.phone?` • ${o.phone}`:''} • ${o.outlet}</p><div class="order-pills">${payPill(o)}${orderPill(o)}</div><div class="ba-summary"><div><span>Estimasi</span><strong>${fmtEta(o)}</strong></div><div><span>Dibuat oleh</span><strong>${o.createdBy}</strong></div><div><span>Total</span><strong>${rupiah(m.total)}</strong></div><div><span>Dibayar</span><strong>${rupiah(m.paid)}</strong></div><div><span>${m.rest<0?'Lebih bayar':'Sisa'}</span><strong class="${m.rest>0?'low':m.rest<0?'over-text':'ok'}">${rupiah(Math.abs(m.rest))}</strong></div><div><span>Fee driver (biaya keluar)</span><strong>${feeText(o.fee)}</strong></div></div>${o.note?`<p>Catatan: ${o.note}</p>`:''}<p class="order-section">Item</p><div class="order-lines">${o.items.map(x=>`<div><span>${x.name} ×${x.qty}</span><strong>${rupiah(x.price*x.qty)}</strong></div>`).join('')||'<div><span>Tidak ada item</span></div>'}</div><p class="order-section">Riwayat pembayaran</p><div class="order-lines">${o.payments.map(p=>`<div><span>${p.at} • ${p.method} • ${p.by}</span><strong>${rupiah(p.amount)}</strong></div>`).join('')||'<div><span>Belum ada pembayaran</span></div>'}</div><div class="modal-actions"><button class="btn ghost" data-close>Tutup</button>${m.rest>0?'<button class="btn ghost" id="orderPay">Catat pembayaran</button>':''}${o.status==='Open'?'<button class="btn primary" id="orderDone">Selesaikan order</button>':''}</div>`);if($('#orderPay'))$('#orderPay').onclick=()=>recordPaymentModal(o);if($('#orderDone'))$('#orderDone').onclick=()=>confirmComplete(o)}
function recordPaymentModal(o){const rest=orderMoney(o).rest;openModal(`<h2>Catat pembayaran</h2><p>${o.id} • ${o.customer}. Sisa tagihan ${rupiah(rest)}.</p><label>Nominal</label><input id="opAmount" type="number" min="1" max="${rest}" value="${rest}"><label>Metode pembayaran</label><select id="opMethod">${PAY_METHODS}</select><div class="modal-actions"><button class="btn ghost" id="opBack">Kembali</button><button class="btn primary" id="opSave">Simpan pembayaran</button></div>`);$('#opBack').onclick=()=>openOrderDetail(o.id);$('#opSave').onclick=()=>{const n=+$('#opAmount').value||0;if(n<=0)return showToast('Nominal pembayaran harus lebih dari 0');if(n>orderMoney(o).rest)return showToast('Nominal melebihi sisa tagihan');o.payments.push({amount:n,method:$('#opMethod').value,by:session.name,at:ORDER_NOW});renderOrders();openOrderDetail(o.id);showToast('Pembayaran tercatat')}}
