function renderOrderForm(){$('#ofTabs').innerHTML=Object.keys(menuData).map(x=>`<button class="${x===orderDraft.category?'active':''}" data-cat="${x}">${x}</button>`).join('');$('#ofTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{orderDraft.category=b.dataset.cat;renderOrderForm()});const q=orderDraft.query.toLowerCase(),items=menuData[orderDraft.category].filter(x=>x[0].toLowerCase().includes(q)||String(x[1]).includes(q));$('#ofGrid').innerHTML=items.map(x=>`<button class="menu-card"><div class="food-art"><span>${x[3]}</span></div><div class="menu-info"><strong>${x[0]}</strong><small>${x[2]}</small><span>${rupiah(x[1])}</span></div></button>`).join('')||'<div class="empty-cart">Menu tidak ditemukan.</div>';$('#ofGrid').querySelectorAll('.menu-card').forEach((b,i)=>b.onclick=()=>{const it=items[i],f=orderDraft.items.find(x=>x.name===it[0]);if(f)f.qty++;else orderDraft.items.push({name:it[0],price:it[1],qty:1});renderOrderDraft()});renderOrderDraft()}
function renderOrderDraft(){const host=$('#ofItems'),prune=()=>{orderDraft.items=orderDraft.items.filter(y=>y.qty>0);renderOrderDraft()};host.innerHTML=orderDraft.items.length?orderDraft.items.map((x,i)=>`<div class="cart-item"><div><strong>${x.name}</strong><small>${rupiah(x.price)} / item</small><div class="qty"><button data-act="minus" data-i="${i}">−</button><input class="qty-input" type="number" min="0" value="${x.qty}" data-i="${i}"><button data-act="plus" data-i="${i}">+</button></div></div><div class="price">${rupiah(x.price*x.qty)}<button class="cancel-link" data-act="del" data-i="${i}">Hapus</button></div></div>`).join(''):`<div class="empty-cart">Belum ada item.<br>Pilih menu dari daftar di kiri.</div>`;host.querySelectorAll('button').forEach(b=>b.onclick=()=>{const x=orderDraft.items[+b.dataset.i];if(b.dataset.act==='plus')x.qty++;if(b.dataset.act==='minus')x.qty--;if(b.dataset.act==='del')x.qty=0;prune()});host.querySelectorAll('.qty-input').forEach(inp=>inp.onchange=()=>{orderDraft.items[+inp.dataset.i].qty=Math.max(0,Math.floor(+inp.value||0));prune()});updateOrderPay()}
function draftTotal(){return orderDraft.items.reduce((s,x)=>s+x.price*x.qty,0)}
function updateOrderPay(){const t=draftTotal(),type=$('input[name=ofPay]:checked').value;$('#ofSubtotal').textContent=rupiah(t);$('#ofPayFields').classList.toggle('hidden',type==='none');$('#ofPayAmount').disabled=type==='full';if(type==='full')$('#ofPayAmount').value=t;const paid=type==='none'?0:+$('#ofPayAmount').value||0;$('#ofRest').textContent=rupiah(t-paid)}
function saveOrder(){const customer=$('#ofCustomer').value.trim(),date=$('#ofDate').value,time=$('#ofTime').value,t=draftTotal(),type=$('input[name=ofPay]:checked').value,amount=+$('#ofPayAmount').value||0,status=$('input[name=ofStatus]:checked').value,feeOn=$('#ofFeeOn').checked,feeType=$('#ofFeeType').value,feeVal=+$('#ofFeeValue').value||0,feeItems=readRokokPicker($('#ofRokokPicker'));
  if(!$('#ofOutlet').value)return showToast('Outlet wajib diisi');if(!customer)return showToast('Nama pelanggan wajib diisi');if(!date||!time)return showToast('Estimasi tanggal dan jam wajib diisi');if(!orderDraft.items.length)return showToast('Pilih minimal satu item');if(type==='partial'&&(amount<=0||amount>=t))return showToast('Nominal sebagian harus lebih dari 0 dan kurang dari total');if(feeOn&&feeType==='cash'&&feeVal<=0)return showToast('Isi nominal fee driver atau hapus centang fee');if(feeOn&&feeType==='stock'&&!feeItems.length)return showToast('Pilih minimal satu merek rokok');
  const o={id:nextOrderId(),outlet:$('#ofOutlet').value,customer,phone:$('#ofPhone').value.trim(),date,time,note:$('#ofNote').value.trim(),items:orderDraft.items.map(x=>({...x})),payments:type==='none'?[]:[{amount:type==='full'?t:amount,method:$('#ofPayMethod').value,by:session.name,at:ORDER_NOW}],fee:!feeOn?null:feeType==='cash'?{type:'cash',value:feeVal}:{type:'stock',items:feeItems},status:'Open',createdBy:session.name};
  scheduledOrders.push(o);if(status==='Selesai')completeOrder(o);orderFilter='Semua';showOrderForm(false);renderOrders();showToast(status==='Selesai'?'Order tersimpan dan stok dipotong':'Order tersimpan')}
$('#addOrder').onclick=()=>showOrderForm(true);$('#ofCancel').onclick=()=>showOrderForm(false);$('#ofSave').onclick=saveOrder;
