function renderCartHeader(sub){const o=activeOrder;$('#addFee').classList.toggle('hidden',!!o?.fee);if(!o){$('#cartOrderNo').textContent='#RBT-0920-087';$('#cartStatus').className='status';$('#cartStatus').textContent='Makan di tempat';$('#customerInfo').innerHTML='<small>Pelanggan</small><strong>Umum</strong>';$('.stock-note').textContent='Stok barang dagangan akan terpotong otomatis setelah pembayaran.';return}const paid=orderMoney(o).paid,s=moneyState(sub,paid);$('#cartOrderNo').textContent=o.id;$('#cartStatus').className=`status ${stateCls(s)}`;$('#cartStatus').textContent=s;$('#customerInfo').innerHTML=`<small>Order terjadwal • ETA ${fmtEta(o)}</small><strong>${o.customer}</strong><small>Dibayar ${rupiah(paid)} dari ${rupiah(sub)}</small>`;$('.stock-note').textContent='Stok dipotong saat order diselesaikan Admin/Kepala Toko.'}
function renderOrderTotals(sub){const o=activeOrder,paid=orderMoney(o).paid,rest=sub-paid,pb=$('#payButton');$('#subtotal').textContent=rupiah(sub);$('#feeLineLabel').textContent='Fee driver';$('#feeTotal').textContent=o.fee?`${feeText(o.fee)} (dari order)`:'';$('#feeLine').classList.toggle('hidden',!o.fee);$('#paidLine').classList.remove('hidden');$('#paidTotal').textContent=`-${rupiah(paid)}`;$('#grandLabel').textContent=rest<0?'Lebih bayar':'Sisa';$('#grandTotal').textContent=rupiah(Math.abs(rest));$('.totals .grand-total').classList.toggle('over-line',rest<0);pb.disabled=rest<=0;pb.querySelector('span').textContent=rest>0?'Terima pembayaran':rest<0?'Lebih bayar':'Lunas';$('#payAmount').textContent=rest===0?'':rupiah(Math.abs(rest))}
