function openOrderPayment(){const o=activeOrder,sub=cart.reduce((s,x)=>s+x.price*x.qty,0),rest=sub-orderMoney(o).paid,added=cart.filter(x=>!x.saved);openModal(`<h2>Terima pembayaran</h2><p>${o.id} • ${o.customer}.${added.length?` ${added.length} item baru akan disimpan ke order.`:''} Stok tidak dipotong saat pembayaran.</p><div style="font:700 34px 'Fraunces';margin:22px 0">${rupiah(rest)}</div><label>Nominal diterima</label><input id="kpAmount" type="number" min="0" max="${rest}" value="${rest}"><label>Metode pembayaran</label><select id="kpMethod">${PAY_METHODS}</select><div class="modal-actions"><button class="btn ghost" data-close>Batal</button><button class="btn primary" id="kpSave">Konfirmasi pembayaran</button></div>`);$('#kpSave').onclick=()=>{const n=Math.max(0,+$('#kpAmount').value||0);if(n>rest)return showToast('Nominal melebihi sisa tagihan');added.forEach(a=>{const f=o.items.find(x=>x.name===a.name);if(f)f.qty+=a.qty;else o.items.push({name:a.name,price:a.price,qty:a.qty})});if(n>0)o.payments.push({amount:n,method:$('#kpMethod').value,by:session.name,at:ORDER_NOW});closeModal();activeOrder=null;cart=[];fee=0;feeRokok=[];renderCart();renderOrders();showToast(n>0?'Pembayaran order tercatat':'Order diperbarui tanpa pembayaran')}}
