let grnSeq=13,reqFilter='Semua',reqQuery='',requestDraft={query:'',status:'Semua',picks:{}};
const REQ_CLS={'Menunggu persetujuan':'wait','Disetujui':'approved','PO dicetak':'printed','Selesai':'done','Ditolak':'rejected'};
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
function reqPill(s){return `<span class="status ${REQ_CLS[s]||''}">${s}</span>`}
function fmtReqDate(d){const [y,m,dd]=d.split('-');return `${+dd} ${MONTHS[+m-1]} ${y}`}
function reqNow(){const d=new Date();return `20 Sep 2026 ${String(d.getHours()).padStart(2,'0')}.${String(d.getMinutes()).padStart(2,'0')}`}
function logReq(r,text){r.history.push({at:reqNow(),by:session.name,text})}
function reqTotal(r){return r.items.reduce((s,x)=>s+x.qty*x.price,0)}
function canActRequest(r){return session?.role==='Administrator'||(session?.role==='Kepala Toko'&&r.outlet===session.outlet)}
function diffText(d,unit){return d===0?'-':`<span class="${d<0?'diff-neg':'diff-pos'}">${d>0?'+':''}${d} ${unit}</span>`}
function renderMaterialRequests(){const q=reqQuery.trim().toLowerCase(),list=materialRequests.filter(r=>(reqFilter==='Semua'||r.status===reqFilter)&&(!q||`${r.id} ${r.by.name}`.toLowerCase().includes(q))).sort((a,b)=>b.id.localeCompare(a.id));$('#requestStatusFilter').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.status===reqFilter));$('#requestCount').textContent=`${list.length} permintaan • klik Detail untuk riwayat`;$('#requestTable').innerHTML=list.length?tableHtml(['NO. PERMINTAAN','TANGGAL','OUTLET','PEMINTA','ITEM','NO. PO','STATUS','AKSI'],list.map(r=>[r.id,fmtReqDate(r.date),r.outlet,`<span class="req-by">${r.by.name}<small>${r.by.role}</small></span>`,`${r.items.length} item`,r.po?.id||'-',reqPill(r.status),`<button class="text-btn" data-req="${r.id}">Detail</button>`])):'<div class="empty-cart">Tidak ada permintaan</div>';$('#requestTable').querySelectorAll('[data-req]').forEach(b=>b.onclick=()=>openRequestDetail(b.dataset.req))}
function openRequestDetail(id){const r=materialRequests.find(x=>x.id===id),admin=session?.role==='Administrator',edit=admin&&r.status==='Menunggu persetujuan',act=canActRequest(r),rc=r.receipt,po=['Disetujui','PO dicetak'].includes(r.status);
  const items=tableHtml(['ITEM','QTY','HARGA PO','SUBTOTAL'],r.items.map((x,i)=>[x.name,edit?`<span class="qty-cell"><input class="req-input" type="number" min="1" value="${x.qty}" data-i="${i}">${x.unit}</span>`:`${x.qty} ${x.unit}`,rupiah(x.price),rupiah(x.qty*x.price)]));
  const recv=rc?`<h3>Penerimaan ${rc.grn}${rc.supplierDoc?` • ${esc(rc.supplierDoc)}`:''}</h3>${tableHtml(['ITEM','QTY PO','DITERIMA','SELISIH'],r.items.map(x=>{const l=rc.lines.find(y=>y.name===x.name)||{qty:0};return [x.name,`${x.qty} ${x.unit}`,`${l.qty} ${x.unit}`,diffText(l.qty-x.qty,x.unit)]}))}${rc.note?`<div class="warning-box"><strong>Catatan selisih</strong><span>${esc(rc.note)}</span></div>`:''}`:'';
  const actions=edit?'<button class="btn ghost" id="rqReject">Tolak</button><button class="btn primary" id="rqApprove">Setujui</button>':act&&po?`<button class="btn ${r.status==='PO dicetak'?'ghost':'primary'}" id="rqPrint">Cetak PO</button>${r.status==='PO dicetak'?'<button class="btn primary" id="rqReceive">Terima barang</button>':''}`:'';
  const info=r.status==='Menunggu persetujuan'&&!admin?'Menunggu persetujuan Administrator':po&&!act?'Hanya dapat dilihat':'';
  openModal(`<div class="req-modal"><h2>${r.id}</h2><p>${r.note?esc(r.note):'Tanpa catatan'}</p><div class="order-pills">${reqPill(r.status)}</div><div class="ba-summary"><div><span>Outlet</span><strong>${r.outlet}</strong></div><div><span>Peminta</span><strong>${r.by.name} • ${r.by.role}</strong></div><div><span>Tanggal</span><strong>${fmtReqDate(r.date)}</strong></div><div><span>No. PO</span><strong>${r.po?.id||'-'}</strong></div><div><span>Vendor</span><strong>${r.po?.vendor.name?esc(r.po.vendor.name):r.po?'Belum diisi':'-'}</strong></div><div><span>Total</span><strong>${rupiah(reqTotal(r))}</strong></div></div>${r.status==='Ditolak'?`<div class="warning-box"><strong>Alasan penolakan</strong><span>${esc(r.rejectReason)}</span></div>`:''}<h3>Item permintaan${edit?' (qty dapat dikoreksi sebelum disetujui)':''}</h3>${items}${recv}<h3>Riwayat</h3><div class="timeline">${r.history.map(h=>`<div class="timeline-item"><div class="timeline-dot">•</div><div><strong>${esc(h.text)}</strong><span>${h.by}</span></div><time>${h.at.slice(-5)}</time></div>`).join('')}</div><div class="modal-actions">${info?`<span class="view-only">${info}</span>`:''}<button class="btn ghost" data-close>Tutup</button>${actions}</div></div>`);
  if(edit){$('#rqApprove').onclick=()=>approveFromDetail(r);$('#rqReject').onclick=()=>rejectRequestModal(r)}
  if($('#rqPrint'))$('#rqPrint').onclick=()=>printPoModal(r);if($('#rqReceive'))$('#rqReceive').onclick=()=>receiveModal(r);
}
$('#requestStatusFilter').querySelectorAll('button').forEach(b=>b.onclick=()=>{reqFilter=b.dataset.status;renderMaterialRequests()});$('#requestSearch').oninput=e=>{reqQuery=e.target.value;renderMaterialRequests()};
renderMaterialRequests();
// Form buat permintaan
function showRequestForm(on){$('#inventory').classList.toggle('req-form-open',on);$('#requestFormPanel').classList.toggle('hidden',!on);$('#inventory .topbar h1').textContent=on?'Buat permintaan barang':'Persediaan';if(on){resetRequestDraft();renderRequestForm()}}
function resetRequestDraft(){requestDraft={query:'',status:'Semua',picks:Object.fromEntries(rawStock.map(x=>[x.name,{checked:x.qty<=x.min,qty:''}]))};$('#rfSearch').value='';$('#rfNote').value='';$('#rfOutletWrap').innerHTML=session?.role==='Kepala Toko'?`<input id="rfOutlet" value="${session.outlet}" disabled>`:`<select id="rfOutlet">${outlets.map(x=>`<option>${x.name}</option>`).join('')}</select>`}
function renderRequestForm(){const d=requestDraft,q=d.query.trim().toLowerCase(),low=x=>x.qty<=x.min;$('#rfStatusFilter').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.status===d.status));
  const rows=rawStock.filter(x=>(d.status==='Semua'||(d.status==='Menipis')===low(x))&&x.name.toLowerCase().includes(q)).sort((a,b)=>low(b)-low(a)||(low(a)?a.qty/a.min-b.qty/b.min:a.name.localeCompare(b.name)));
  $('#rfTable').innerHTML=rows.length?tableHtml(['','ITEM','STOK','MINIMUM','STATUS','BIAYA / UNIT','QTY DIMINTA'],rows.map(x=>{const p=d.picks[x.name];return [`<input type="checkbox" data-name="${x.name}" ${p.checked?'checked':''}>`,x.name,`${x.qty} ${x.unit}`,`${x.min} ${x.unit}`,`<span class="${low(x)?'low':'ok'}">${low(x)?'Menipis':'Aman'}</span>`,rupiah(x.cost),`<span class="qty-cell"><input class="req-input rf-qty" type="number" min="1" data-name="${x.name}" value="${esc(p.qty)}" placeholder="0">${x.unit}</span>`]})):'<div class="empty-cart">Tidak ada bahan baku yang cocok</div>';
  $('#rfTable').querySelectorAll('input[type=checkbox]').forEach(c=>c.onchange=()=>{d.picks[c.dataset.name].checked=c.checked;updateRequestSummary()});
  $('#rfTable').querySelectorAll('.rf-qty').forEach(i=>i.oninput=()=>{const p=d.picks[i.dataset.name];p.qty=i.value;if(+i.value>0&&!p.checked){p.checked=true;$(`#rfTable input[type=checkbox][data-name="${i.dataset.name}"]`).checked=true}updateRequestSummary()});updateRequestSummary()}
function updateRequestSummary(){const p=requestDraft.picks,sel=rawStock.filter(x=>p[x.name].checked),est=sel.reduce((s,x)=>s+(+p[x.name].qty>0?+p[x.name].qty*x.cost:0),0);$('#rfSummary').textContent=`${sel.length} item dipilih • Estimasi ${rupiah(est)}`}
function nextReqId(){return `REQ-0920-${String(materialRequests.length+1).padStart(3,'0')}`}
function submitRequest(){const p=requestDraft.picks,sel=rawStock.filter(x=>p[x.name].checked);if(!sel.length)return showToast('Pilih minimal satu bahan baku');const bad=sel.find(x=>!(+p[x.name].qty>0));if(bad)return showToast(`Isi qty untuk ${bad.name}`);
  const r={id:nextReqId(),outlet:$('#rfOutlet').value,date:'2026-09-20',by:{name:session.name,role:session.role},note:$('#rfNote').value.trim(),status:'Menunggu persetujuan',items:sel.map(x=>({name:x.name,unit:x.unit,qty:+p[x.name].qty,price:x.cost})),rejectReason:'',po:null,receipt:null,history:[]};
  logReq(r,'Permintaan diajukan');materialRequests.push(r);if(session.role==='Administrator'){approveRequest(r,true);showToast(`Permintaan ${r.id} disetujui otomatis, ${r.po.id} siap dicetak`)}else showToast(`Permintaan ${r.id} diajukan, menunggu persetujuan Administrator`);reqFilter='Semua';showRequestForm(false);renderMaterialRequests()}
$('#addRequest').onclick=()=>showRequestForm(true);$('#rfCancel').onclick=()=>showRequestForm(false);$('#rfSubmit').onclick=submitRequest;
$('#rfStatusFilter').querySelectorAll('button').forEach(b=>b.onclick=()=>{requestDraft.status=b.dataset.status;renderRequestForm()});$('#rfSearch').oninput=e=>{requestDraft.query=e.target.value;renderRequestForm()};
// Approval, cetak PO, terima barang
function approveRequest(r,auto){r.po={id:r.id.replace('REQ','PO'),vendor:{name:'',contact:'',phone:'',address:''},printed:false};r.status='Disetujui';logReq(r,auto?'Disetujui otomatis (Administrator)':`Disetujui oleh ${session.name}`)}
function approveFromDetail(r){const vals=[...$$('#modalContent .req-input')].map(i=>+i.value),bad=vals.findIndex(v=>!(v>0));if(bad>=0)return showToast(`Isi qty untuk ${r.items[bad].name}`);r.items.forEach((x,i)=>{if(vals[i]!==x.qty){logReq(r,`Qty ${x.name} dikoreksi ${x.qty} → ${vals[i]} ${x.unit}`);x.qty=vals[i]}});approveRequest(r,false);renderMaterialRequests();openRequestDetail(r.id);showToast(`${r.id} disetujui, ${r.po.id} siap dicetak`)}
function rejectRequestModal(r){openModal(`<h2>Tolak permintaan</h2><p>${r.id} • ${r.by.name}. Alasan penolakan akan tampil di detail dan riwayat permintaan.</p><label>Alasan penolakan</label><textarea id="rqReason" rows="3" placeholder="Mis. stok masih cukup"></textarea><div class="modal-actions"><button class="btn ghost" id="rqBack">Kembali</button><button class="btn danger" id="rqRejectYes">Tolak permintaan</button></div>`);$('#rqBack').onclick=()=>openRequestDetail(r.id);$('#rqRejectYes').onclick=()=>{const why=$('#rqReason').value.trim();if(!why)return showToast('Alasan penolakan wajib diisi');r.rejectReason=why;r.status='Ditolak';logReq(r,`Ditolak: ${why}`);renderMaterialRequests();openRequestDetail(r.id);showToast(`${r.id} ditolak`)}}
function poDocHtml(r){const v=r.po.vendor,o=outlets.find(x=>x.name===r.outlet),appr=r.history.find(h=>h.text.startsWith('Disetujui'));return `<div class="po-doc"><header><div><h1>PURCHASE ORDER</h1><p>${r.outlet}${o?` • ${o.code} • ${o.city}`:''}</p></div><div class="po-meta"><strong>${r.po.id}</strong><span>Ref. permintaan ${r.id}</span><span>Tanggal ${fmtReqDate(r.date)}</span></div></header><div class="po-parties"><div><small>KEPADA VENDOR</small><strong>${esc(v.name)}</strong>${v.contact?`<br>Up. ${esc(v.contact)}`:''}${v.phone?`<br>Telp. ${esc(v.phone)}`:''}${v.address?`<br>${esc(v.address)}`:''}</div><div><small>DIKIRIM KE</small><strong>${r.outlet}</strong>${o?`<br>${o.city}`:''}<br>Peminta: ${r.by.name} (${r.by.role})</div></div><table><thead><tr><th>NO</th><th>ITEM</th><th class="num">QTY</th><th class="num">HARGA</th><th class="num">SUBTOTAL</th></tr></thead><tbody>${r.items.map((x,i)=>`<tr><td>${i+1}</td><td>${x.name}</td><td class="num">${x.qty} ${x.unit}</td><td class="num">${rupiah(x.price)}</td><td class="num">${rupiah(x.qty*x.price)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="4" class="num">TOTAL</td><td class="num">${rupiah(reqTotal(r))}</td></tr></tfoot></table>${r.note?`<p class="po-note">Catatan: ${esc(r.note)}</p>`:''}<div class="po-sign"><div>Dibuat oleh<span>${r.by.name}</span></div><div>Disetujui oleh<span>${appr?.by||'-'}</span></div></div></div>`}
function printPoModal(r){const v=r.po.vendor;openModal(`<div class="req-modal"><h2>Cetak ${r.po.id}</h2><p>${r.id} • ${r.outlet}. Identitas vendor dan harga PO disimpan pada PO ini saja dan tidak mengubah harga master bahan baku.</p><div class="form-grid"><label>Nama vendor<input id="poVendor" value="${esc(v.name)}" placeholder="Nama vendor / pemasok"></label><label>Kontak<input id="poContact" value="${esc(v.contact)}" placeholder="Nama kontak"></label><label>Telepon<input id="poPhone" value="${esc(v.phone)}" placeholder="08xx / 024-xxx"></label><label>Alamat<input id="poAddress" value="${esc(v.address)}" placeholder="Alamat vendor"></label></div><h3>Harga PO</h3>${tableHtml(['ITEM','QTY','HARGA MASTER','HARGA PO','SUBTOTAL'],r.items.map(x=>[x.name,`${x.qty} ${x.unit}`,rupiah(rawStock.find(s=>s.name===x.name)?.cost||0),`<input class="req-input wide po-price" type="number" min="0" value="${x.price}">`,`<span class="po-sub">${rupiah(x.qty*x.price)}</span>`]))}<div class="req-total" id="poTotal"></div><div class="modal-actions"><button class="btn ghost" data-close>Batal</button><button class="btn primary" id="poSave">Simpan &amp; cetak PO</button></div></div>`);
  const prices=()=>[...$$('#modalContent .po-price')].map(i=>Math.max(0,+i.value||0)),sync=()=>{const p=prices();$$('#modalContent .po-sub').forEach((s,i)=>s.textContent=rupiah(r.items[i].qty*p[i]));$('#poTotal').textContent=`Total PO ${rupiah(r.items.reduce((s,x,i)=>s+x.qty*p[i],0))}`};$$('#modalContent .po-price').forEach(i=>i.oninput=sync);sync();
  $('#poSave').onclick=()=>{const name=$('#poVendor').value.trim();if(!name)return showToast('Nama vendor wajib diisi');const p=prices();r.po.vendor={name,contact:$('#poContact').value.trim(),phone:$('#poPhone').value.trim(),address:$('#poAddress').value.trim()};r.items.forEach((x,i)=>x.price=p[i]);$('#poPrint').innerHTML=poDocHtml(r);document.body.classList.add('print-po');window.print();document.body.classList.remove('print-po');if(!r.po.printed){r.po.printed=true;r.status='PO dicetak';logReq(r,'PO dicetak')}else logReq(r,'PO dicetak ulang');closeModal();renderMaterialRequests();showToast(`${r.po.id} dicetak`)}}
function receiveModal(r){const grn=`GRN-0920-${String(grnSeq).padStart(3,'0')}`;openModal(`<div class="req-modal"><h2>Terima barang dari ${r.po.id}</h2><p>${r.id} • ${r.outlet}. Penerimaan menambah LPP bahan baku sesuai qty diterima dan memperbarui biaya per unit dengan harga diterima.</p><div class="form-grid"><label>No. penerimaan<input value="${grn}" disabled></label><label>Tanggal<input type="date" value="2026-09-20"></label><label>Pemasok<input value="${esc(r.po.vendor.name)}" disabled></label><label>No. surat jalan<input id="rcDoc" placeholder="Mis. SJ-88219"></label></div><h3>Barang diterima</h3>${tableHtml(['ITEM','QTY PO','QTY DITERIMA','HARGA','SELISIH'],r.items.map(x=>[x.name,`${x.qty} ${x.unit}`,`<span class="qty-cell"><input class="req-input rc-qty" type="number" min="0" value="${x.qty}">${x.unit}</span>`,`<input class="req-input wide rc-price" type="number" min="0" value="${x.price}">`,'<span class="rc-diff">-</span>']))}<div class="req-total" id="rcTotal"></div><label>Catatan selisih <span id="rcNoteHint" class="low"></span></label><textarea id="rcNote" rows="2" placeholder="Wajib diisi jika qty diterima berbeda dari PO"></textarea><div class="modal-actions"><button class="btn ghost" id="rcBack">Kembali</button><button class="btn primary" id="rcSave">Simpan penerimaan</button></div></div>`);
  const read=()=>r.items.map((x,i)=>({x,qty:Math.max(0,+$$('#modalContent .rc-qty')[i].value||0),price:Math.max(0,+$$('#modalContent .rc-price')[i].value||0)})),sync=()=>{const L=read();L.forEach((l,i)=>$$('#modalContent .rc-diff')[i].innerHTML=diffText(l.qty-l.x.qty,l.x.unit));$('#rcTotal').textContent=`Total nilai diterima ${rupiah(L.reduce((s,l)=>s+l.qty*l.price,0))}`;$('#rcNoteHint').textContent=L.some(l=>l.qty!==l.x.qty)?'(wajib, ada selisih qty)':''};
  $$('#modalContent .rc-qty,#modalContent .rc-price').forEach(i=>i.oninput=sync);sync();$('#rcBack').onclick=()=>openRequestDetail(r.id);
  $('#rcSave').onclick=()=>{const L=read(),diffs=L.filter(l=>l.qty!==l.x.qty),note=$('#rcNote').value.trim();if(diffs.length&&!note)return showToast('Catatan selisih wajib diisi karena qty diterima berbeda dari PO');L.forEach(l=>{const s=rawStock.find(y=>y.name===l.x.name);if(s){s.qty+=l.qty;s.cost=l.price}});r.receipt={grn,supplierDoc:$('#rcDoc').value.trim(),lines:L.map(l=>({name:l.x.name,qty:l.qty,price:l.price})),note};grnSeq++;r.status='Selesai';logReq(r,`Diterima dengan ${grn}`);if(diffs.length)logReq(r,`Selisih ${diffs.map(l=>`${l.x.name} ${l.qty>l.x.qty?'+':''}${l.qty-l.x.qty} ${l.x.unit}`).join(', ')}: ${note}`);renderInventory();renderMaterialRequests();closeModal();showToast(`Barang ${r.po.id} diterima, stok bahan baku diperbarui`)}}
